INSERT
INTO
		CL_NOTICE
VALUES
		(
		  SEQ_NOTICE_NO.NEXTVAL
		, #{noticeWriter}
		, #{noticeTitle}
		, #{noticeContent}
		, DEFAULT
		, SYSDATE
		, 'Y'
		, #{fix}
		)

    INSERT
	INTO 
